vertex:
#version 300 es
layout(location = 0) in vec3 position;
layout(location = 3) in vec4 vertexColor;

uniform mat4 viewProjection;
uniform mat4 model;
out vec3 v_position;
out vec4 v_color;

void main() {
  v_position = position;
  v_color = vertexColor;
  gl_Position = viewProjection * model * vec4(position, 1.0);
}

fragment:
#version 300 es
precision highp float;

in vec3 v_position;
in vec4 v_color;
uniform float opacity;

out vec4 fragColor;

void main() {
  vec3 n0 = v_position;
  vec2 n1 = n0.xy;
  vec2 n2 = vec2(0.25, -0.5);
  vec2 n3 = (n1 - n2);
  float n4 = length(n3);
  float n5 = 0.6666666666666666;
  float n6 = (n4 * n5);
  vec4 n7 = vec4(1.0, 0.9, 0.4, 0.875);
  float n8 = 0.0;
  float n9 = (n6 - n8);
  float n10 = 2.0;
  float n11 = (n9 * n10);
  float n12 = clamp(n11, 0.0, 1.0);
  vec4 n13 = vec4(0.0, -0.5, -0.4, 0.0);
  vec4 n14 = (n13 * n12);
  vec4 n15 = (n7 + n14);
  float n16 = 0.5;
  float n17 = step(n16, n6);
  vec4 n18 = vec4(-0.8, -0.4, 0.4, 0.0);
  vec4 n19 = (n18 * n17);
  vec4 n20 = (n15 + n19);
  float n21 = 0.5;
  float n22 = (n6 - n21);
  float n23 = 2.0;
  float n24 = (n22 * n23);
  float n25 = clamp(n24, 0.0, 1.0);
  vec4 n26 = vec4(-0.2, 0.0, -0.30000000000000004, 0.0);
  vec4 n27 = (n26 * n25);
  vec4 n28 = (n20 + n27);
  vec4 n29 = vec4(1.0, 1.0, 1.0, 0.5);
  vec4 n30 = v_color;
  float n31 = n30.x;
  vec4 n32 = mix(n28, n29, n31);
  vec4 c = n32;
  fragColor = vec4(c.rgb, c.a * opacity);
}
